    if text[0] == '-':
        raise ValueError('Negative input not allowed')
    # Count decimal separators
    dot_count = text.count('.')
    comma_count = text.count(',')
    if dot_count + comma_count != 1:
        raise ValueError('Only one decimal separator allowed')
    # Replace comma with dot if comma present
    if ',' in text:
        text = text.replace(',', '.')
    # Now text should contain exactly one dot
    if '.' not in text:
        # Could be integer (no separator) but we required exactly one separator; if none, reject?
        raise ValueError('Missing decimal separator')
    # Ensure dot is not at start or end
    if text[0] == '.' or text[-1] == '.':
        raise ValueError('Invalid decimal format')
